<template><label class="sf-choice" :class="{'is-disabled':disabled}"><input :type="type" :name="name" :checked="checked" :disabled="disabled" :value="option" @change="change"/><span><strong>{{ label }}</strong><small v-if="description">{{ description }}</small></span></label></template>
<script>export default {name:'SfChoice',props:{value:[Boolean,String,Number],option:[String,Number],name:String,label:{type:String,required:true},description:String,type:{type:String,default:'checkbox',validator:v=>['checkbox','radio'].includes(v)},disabled:Boolean},computed:{checked(){return this.type==='radio'?this.value===this.option:!!this.value}},methods:{change(event){this.$emit('input',this.type==='radio'?this.option:event.target.checked)}}}</script>
